package com.pocketsamp.server

/**
 * Localisation for the embedded PocketSAMP UI.
 *
 * English is the fallback for any missing entry.
 */
object Locales {

    enum class Lang { ID, EN, ES, RU, TL }

    /** The language of the running UI; the host (PawnMC) sets it at launch. */
    @Volatile
    var current: Lang = Lang.EN
        private set

    /** Theme mode of the running UI, following the main app. */
    enum class Theme { LIGHT, DARK, SYSTEM }

    @Volatile
    var theme: Theme = Theme.SYSTEM
        private set

    /** Called by the host before [ServerApp.launch] so the UI matches the PawnMC setting. */
    fun setLanguage(lang: Lang) {
        current = lang
    }

    /** Called by the host before [ServerApp.launch] so the UI follows the PawnMC theme. */
    fun setTheme(mode: Theme) {
        theme = mode
    }

    /** Convenience lookup for composables that did not receive a lang parameter. */
    fun text(key: String): String = text(current, key)

    /** Short `[hh:mm:ss]` stamp for console lines. */
    fun stamp(): String =
        java.text.SimpleDateFormat("HH:mm:ss", java.util.Locale.ROOT).format(java.util.Date())

    /** `[hh:mm:ss]` prefix followed by the tag body. */
    fun tagged(tag: String, lang: Lang = current): String = "[${stamp()}] $tag"

    /** Double-dot emphasis prefix. */
    fun ellipsis(lang: Lang = current): String = text(lang, "sys.prepend")

    /** Adds a light double-dot emphasis before an existing phrase. */
    fun emphasize(line: String, lang: Lang = current): String = ellipsis(lang) + line

    /** Look up [key]; falls back to the English entry, then the key itself. */
    fun text(lang: Lang, key: String): String {
        val table = translations[key] ?: return key
        return table[lang] ?: table[Lang.EN] ?: key
    }

